import re
import sqlite3

import requests
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("bank-accounts")

DB_PATH = "bank.db"
NOTIFY_URL = "https://notify.internal.example/v1/send"
EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")


@mcp.tool()
def update_account_alert_email_and_notify(account_id: str, new_email: str) -> dict:
    if not account_id or not account_id.strip():
        return {"ok": False, "error": "account_id is required"}
    if not EMAIL_RE.match(new_email or ""):
        return {"ok": False, "error": "invalid email address"}
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute("SELECT status FROM accounts WHERE id = ?", (account_id,)).fetchone()
        if row is None:
            return {"ok": False, "error": "account not found"}
        if row[0] == "closed":
            return {"ok": False, "error": "account is closed"}
        conn.execute("UPDATE accounts SET alert_email = ? WHERE id = ?", (new_email, account_id))
        conn.commit()
    finally:
        conn.close()
    resp = requests.post(
        NOTIFY_URL,
        json={"to": new_email, "template": "alert_email_changed", "account_id": account_id},
        timeout=10,
    )
    return {"ok": True, "notified": resp.ok}

import sqlite3
from dataclasses import dataclass
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("bank-accounts")

DB_PATH = "bank.db"


@dataclass
class InterestResult:
    success: bool
    account_id: str
    interest_added: str = "0.00"
    new_balance: str = "0.00"
    message: str = ""


def _cents(value: Decimal) -> Decimal:
    return value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


@mcp.tool()
def apply_monthly_interest(account_id: str, annual_rate_percent: float) -> dict:
    if annual_rate_percent < 0 or annual_rate_percent > 100:
        return InterestResult(False, account_id, message="rate out of range").__dict__
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute(
            "SELECT balance, type, status FROM accounts WHERE id = ?", (account_id,)
        ).fetchone()
        if row is None:
            return InterestResult(False, account_id, message="account not found").__dict__
        balance = Decimal(str(row[0]))
        if row[1] != "savings":
            return InterestResult(False, account_id, message="not a savings account").__dict__
        if row[2] != "active":
            return InterestResult(False, account_id, message="account not active").__dict__
        monthly_rate = Decimal(str(annual_rate_percent)) / Decimal(100) / Decimal(12)
        interest = _cents(balance * monthly_rate)
        new_balance = balance + interest
        now = datetime.now(timezone.utc).isoformat()
        conn.execute("UPDATE accounts SET balance = ? WHERE id = ?", (str(new_balance), account_id))
        conn.execute(
            "INSERT INTO transactions (account_id, kind, amount, created_at) VALUES (?, 'interest', ?, ?)",
            (account_id, str(interest), now),
        )
        conn.commit()
        return InterestResult(
            True, account_id, str(interest), str(new_balance), "interest applied"
        ).__dict__
    except sqlite3.Error as exc:
        conn.rollback()
        return InterestResult(False, account_id, message=str(exc)).__dict__
    finally:
        conn.close()
